  if (!record2 || recordTenant && recordTenant !== scope2.tenant_id || recordCompany && recordCompany !== scope2.company_id) {
    return json({ ok: false, error: "document_not_found" }, 404);
  }
  const exportObj = record2.billit_export && typeof record2.billit_export === "object" && !Array.isArray(record2.billit_export) ? record2.billit_export : null;
  const exportOrderId = safeStr(exportObj?.order_id, 120);
