async function stampConsumerSaleMarkersOnBooking(env, bookingId, markers = {}) {
  try {
    const loaded = await loadBookingRecord(env, bookingId);
    const rec = loaded?.rec;
    if (!rec || typeof rec !== "object") return false;
    rec.consumer_sale = {
      ...rec.consumer_sale && typeof rec.consumer_sale === "object" ? rec.consumer_sale : {},
      ...markers,
      sale_kind: CONSUMER_SALE_KIND,
      updated_at: (/* @__PURE__ */ new Date()).toISOString()
    };
    const peppol = consumerSalePeppolPolicy();
    rec.consumer_sale.peppol_applicable = peppol.peppol_applicable;
    rec.consumer_sale.peppol_required = peppol.peppol_required;
    await env.BOOKING_KV.put(loaded.key, JSON.stringify(rec));
    return true;
  } catch (_) {
    return false;
  }
}
async function stampConsumerSaleFailureOnBooking(env, bookingId, { reason = "consumer_sale_failed", sourceLegId = null, retryable = true } = {}) {
  return stampConsumerSaleMarkersOnBooking(env, bookingId, {
    status: "issue_failed",
    last_error: safeStr(reason, 120) || "consumer_sale_failed",
    retryable: retryable !== false,
    source_leg_id: safeStr(sourceLegId, 200) || null
  });
}
async function reconcileConsumerSaleForCompletedBooking(env, scope2, bookingId, options = {}) {
  const opts = options && typeof options === "object" ? options : {};
  const source = safeStr(opts.source, 80) || "consumer_sale_reconcile";
  let rec = opts.rec && typeof opts.rec === "object" ? opts.rec : null;
  if (!rec) {
    try {
      rec = (await loadBookingRecord(env, bookingId))?.rec || null;
    } catch (_) {
      rec = null;
    }
  }
  if (!rec) return { ok: false, skipped: true, reason: "booking_not_found" };
  const monthlyDelivery = companyPerRideInvoiceDecision(rec, scope2);
  if (monthlyDelivery.blocked) return { ok: true, skipped: true, reason: monthlyDelivery.error };
  if (canIssueBusinessInvoiceFromRecord(rec)) {
    return { ok: true, skipped: true, reason: "business_invoice_issuable" };
  }
  const status = _normLifecycleStatus(rec?.status ?? rec?.stage ?? null);
  if (status !== "COMPLETED" && !isBookingCompletedForConsumerSale(rec)) {
    return { ok: true, skipped: true, reason: "not_completed" };
  }
  const wantLegId = safeStr(opts.sourceLegId, 200) || null;
  if (!wantLegId && opts._fromMultiLegExpand !== true) {
    const operationalLegs = _bookingOperationalLegsFromRecord2(rec).map((entry) => entry && typeof entry === "object" ? entry : null).filter((entry) => !!entry);
    if (operationalLegs.length > 1) {
      const results = [];
      for (const leg of operationalLegs) {
        const legId = safeStr(leg?.leg_id ?? leg?.legId, 200) || "";
        if (!legId) continue;
        const legStatus = _normLifecycleStatus(
          leg?.status ?? leg?.lifecycle_status ?? leg?.lifecycleStatus ?? null
        );
        if (legStatus !== "COMPLETED") continue;
        const legType = safeStr(leg?.leg_type ?? leg?.legType, 24) || null;
        results.push(
          await reconcileConsumerSaleForCompletedBooking(env, scope2, bookingId, {
            ...opts,
            rec,
            sourceLegId: legId,
            sourceLegType: legType,
            source: `${source}:multi_leg`,
            _fromMultiLegExpand: true
          })
        );
      }
      if (results.length > 0) {
        const anyCreated = results.some(
          (r) => r && r.ok !== false && r.skipped !== true && r.reason !== "idempotent_reuse"
        );
        const anyDoc = results.find((r) => r?.document_id)?.document_id || null;
        return {
          ok: true,
          skipped: !anyCreated,
          reason: "multi_leg_reconcile",
          document_id: anyDoc,
          legs: results.length,
          results
        };
      }
    }
  }
  const existing = await findExistingConsumerSaleDocumentForBooking(
    env,
    scope2,
    bookingId,
    { sourceLegId: opts.sourceLegId || null }
  );
  if (existing?.document_id && existing?.billit_order_id) {
    await stampConsumerSaleMarkersOnBooking(env, bookingId, {
      document_id: existing.document_id,
      document_number: existing.document_number,
      billit_order_id: existing.billit_order_id,
      status: "registered"
    });
    return {
      ok: true,
      skipped: false,
      reason: "idempotent_reuse",
      document_id: existing.document_id,
      billit_order_id: existing.billit_order_id
    };
  }
  console.log(
    `[CONSUMER_BILLIT_SALE][RECONCILE] booking=${_bookingIntentMask(bookingId)} source=${source} has_doc=${!!existing?.document_id}`
  );
  const registered = await maybeRegisterConsumerBillitSaleAfterCompletion(
    env,
    scope2,
    bookingId,
    {
      rec,
      sourceLegId: opts.sourceLegId || null,
      sourceLegType: opts.sourceLegType || null
    }
  );
  const paymentFields = _bookingPaymentFieldsForBillitSync(rec);
  if (paymentFields?.payment_status === "paid") {
    await maybeSyncConsumerBillitSaleAfterPaid(env, scope2, bookingId, {
      rec,
      sourceLegId: opts.sourceLegId || null,
      sourceLegType: opts.sourceLegType || null
    });
  }
  return registered;
}
